    /// Why the schema cannot be applied there.
    pub fn apply(
        edit: &mut SchemaEdit<'_>,
        path: PathId,
        instance: &str,
    ) -> Result<CollectionApiEdit, CannotApply> {
        edit.apply(path, Self::SCHEMA, Some(instance))?;
        Ok(CollectionApiEdit::from_path(path, instance))
    }

